package com.dexm.personajes.adapter.out.persistence;
import jakarta.persistence.*;
@Entity @Table(name="armor_catalog") public class ArmorCatalogEntity { @Id private String id; @Column(nullable=false) private String name; @Column(columnDefinition="text") private String description; @Column(name="slots_json",nullable=false,columnDefinition="text") private String slotsJson; @Column(name="image_url",columnDefinition="longtext") private String imageUrl; @Column(nullable=false) private boolean official; protected ArmorCatalogEntity(){} public ArmorCatalogEntity(String i,String n,String d,String s,String u,boolean o){id=i;name=n;description=d;slotsJson=s;imageUrl=u;official=o;} public String getId(){return id;} public String getName(){return name;} public String getDescription(){return description;} public String getSlotsJson(){return slotsJson;} public String getImageUrl(){return imageUrl;} public boolean isOfficial(){return official;} }
